# SPDX-License-Identifier: MIT
"""Finite returned-buffer failure DATA for the fixed disposable inspect call."""
import base64, hashlib, json, math, re, zlib

KEYS={'argv','exit_code','seconds','time_limit','output_limit','group_absence_verified','stdout_bytes','stdout_sha256','stderr_bytes','stderr_sha256'}
PATH='/execution/scripts/ci/apps7-full574-repair-native/transaction.py'
PREFIX='APPS574_INSPECT_FAILURE '

def encoded(value):
 return json.dumps(value,sort_keys=True,separators=(',',':'),ensure_ascii=True,allow_nan=False)

def sha(raw):return hashlib.sha256(raw).hexdigest()

def role(argv,seconds,expected):
 if type(argv)is not list or len(argv)!=23 or any(type(v)is not str or len(v)>256 for v in argv) or type(seconds)is not int or seconds!=610 or type(expected)is not int or expected!=0:return False
 if argv[:5]!=['/usr/bin/python3','-I','-B',PATH,'inspect']:return False
 keys=['--workspace','--apps-source','--apps-provenance-sha256','--repository-source','--full574-policy','--full574-policy-sha256','--full574-lease','--full574-lease-sha256','--ownership-sha256']
 if argv[5::2]!=keys:return False
 values=dict(zip(keys,argv[6::2]))
 fixed={'--apps-source':'/inputs/apps-source','--repository-source':'/inputs/candidate/usr/share/cachy-asahi/repository-runtime','--full574-policy':'/inputs/full574-policy.json','--full574-lease':'/inputs/full574-lease.json'}
 return values['--workspace']in('/work/main','/work/interrupted') and all(values[k]==v for k,v in fixed.items()) and all(re.fullmatch('[a-f0-9]{64}',values[k])for k in('--apps-provenance-sha256','--full574-policy-sha256','--full574-lease-sha256','--ownership-sha256'))

def note(record,out,err,error,expected=0):
 """No reads, clocks, actors or caller changes; unavailable DATA returns None."""
 if type(record)is not dict or set(record)!=KEYS or not role(record['argv'],record['time_limit'],expected):return None
 if type(out)is not bytes or type(err)is not bytes or len(out)+len(err)>1024**2:return None
 if type(record['exit_code'])is not int or not -255<=record['exit_code']<=255 or type(record['group_absence_verified'])is not bool:return None
 if type(record['seconds'])not in(int,float) or not math.isfinite(record['seconds']) or record['seconds']<0 or type(record['output_limit'])is not int or record['output_limit']!=1024**2:return None
 if record['exit_code']==0 and record['group_absence_verified']:return None
 if error is not None and not isinstance(error,BaseException):return None
 for side,raw in(('stdout',out),('stderr',err)):
  if type(record[side+'_bytes'])is not int or record[side+'_bytes']!=len(raw) or record[side+'_sha256']!=sha(raw):return None
 error_name=None if error is None else type(error).__name__
 if error_name is not None and re.fullmatch('[A-Za-z_][A-Za-z0-9_]{0,127}',error_name)is None:return None
 value={'schema_version':1,'role':'OWNED_COPY_INSPECT','purpose':'RETURNED_FAILURE_DATA_ONLY','source_argv_sha256':sha(encoded(record['argv']).encode()),'supervisor_sha256':sha(encoded(record).encode()),'supervisor_codec':'CANONICAL_COMPACT_ASCII_JSON','supervisor':{k:record[k]for k in KEYS-{'argv'}},'supervisor_error':error_name,'capture':'HASH_AND_LENGTH_ONLY','acceptance_authority':False,'cleanup_authority':False}
 summary=PREFIX+encoded(value)
 if len(summary.encode())>1900:return None
 # Each exposed stream is COMPLETE original DATA, never a tail or truncation.
 streams={side:{'encoding':'ZLIB_BASE64','base64':base64.b64encode(zlib.compress(raw,9)).decode()}for side,raw,cap in(('stdout',out,1024),('stderr',err,65536))if len(raw)<=cap}
 choices=((('stdout','stderr'),'COMPLETE_RETURNED_BUFFERS'),(('stdout',),'COMPLETE_STDOUT_STDERR_HASH_ONLY'),(('stderr',),'COMPLETE_STDERR_STDOUT_HASH_ONLY'))
 for sides,capture in choices:
  if not all(side in streams for side in sides):continue
  full=PREFIX+encoded(dict(value,capture=capture,streams={side:streams[side]for side in sides}))
  if len(full.encode())<=1900:return full
 return summary
